from collections import Counter
import re

class NLPDataProcessor2:

    TOP_K = 5

    def process_data(self, string_list):
        words_list = []
        for string in string_list:
            processed_string = self._clean_string(string)
            words = self._extract_words(processed_string)
            words_list.append(words)
        return words_list

    def _clean_string(self, string):
        return re.sub(r'[^a-zA-Z\s]', '', string.lower())

    def _extract_words(self, processed_string):
        return processed_string.split()

    def calculate_word_frequency(self, words_list):
        word_frequency = self._count_words(words_list)
        sorted_word_frequency = self._sort_word_frequency(word_frequency)
        return self._get_top_k_words(sorted_word_frequency, self.TOP_K)

    def _count_words(self, words_list):
        word_frequency = Counter()
        for words in words_list:
            word_frequency.update(words)
        return word_frequency

    def _sort_word_frequency(self, word_frequency):
        return dict(sorted(word_frequency.items(), key=lambda x: x[1], reverse=True))

    def _get_top_k_words(self, sorted_word_frequency, k):
        return dict(list(sorted_word_frequency.items())[:k])

    def process(self, string_list):
        return self.calculate_word_frequency(self.process_data(string_list))
